+    },
+    {
+      "id": "claim_58d8e0d94a4e438f82635f9fc9c7de34",
+      "statement": "evaluateInboundPolicy (src/agent-host/channels/policy.ts) allows open DMs and allowlisted senders, pairs unknown senders under the pairing policy, and ignores others; group messages additionally require the group policy, requireMention, and allowlist matches.",
+      "evidence": [
+        {
+          "resource": "repo://src/agent-host/channels/policy.ts",
+          "version": "repo-file-v1:sha256:76934881aa9ddad1029a0f7135281e927693cb8e91b0baf81978d701c3f56503"
+        }
+      ]
+    },
+    {
+      "id": "claim_1fbff3885eec420097e36c816fa7fe06",
+      "statement": "Inbound messages are processed serially per route key through LaneScheduler, which runs up to maxConcurrent (default 4) unrelated lanes in parallel while preserving per-conversation ordering.",
+      "evidence": [
+        {
+          "resource": "repo://src/agent-host/channels/channel-manager.ts",
+          "version": "repo-file-v1:sha256:4b77ff02663b2f005e7acb23a8aa7de403bc2b742d152f9cbe47a41ff40a223c"
+        },
+        {
+          "resource": "repo://src/agent-host/channels/lane-scheduler.ts",
+          "version": "repo-file-v1:sha256:5d71b8dd0dca853c16fe44f6ad1bdc9c8376eb88d7fa6dbedc0225c291fc7fdb"
+        }
+      ]
+    },
+    {
+      "id": "claim_c561846a8ad74390b746cca719cfc0fd",
+      "statement": "Pairing approvals (PAIRING_TTL_MS=10min) add the peer id to allowFrom when approved; rejected or expired pairings are dropped.",
+      "evidence": [
+        {
+          "resource": "repo://src/agent-host/channels/channel-manager.ts",
+          "version": "repo-file-v1:sha256:4b77ff02663b2f005e7acb23a8aa7de403bc2b742d152f9cbe47a41ff40a223c"
+        }
+      ]
+    },
+    {
+      "id": "claim_1b770b56508b479796e20d497152b73d",
+      "statement": "PiSessionBridge (src/agent-host/channels/pi-session-bridge.ts) opens or resumes an agent session in a binding's cwd, passing the account toolNames, and drives runs through the existing RPC session machinery.",
+      "evidence": [
+        {
+          "resource": "repo://src/agent-host/channels/pi-session-bridge.ts",
+          "version": "repo-file-v1:sha256:d8c3b8ac4aa6a6241e5756fa8f71df092d96ffdb5db4da9fc70530b08a894f0d"
+        }
+      ]
+    },
+    {
+      "id": "claim_93831196c9d34d9286bbd73a8457fbc4",
+      "statement": "Outbound file sends via the channel bridge require an explicit user request and enforce size/count limits (20 MiB, four files) plus outside-workspace and symlink guards.",
+      "evidence": [
+        {
+          "resource": "repo://src/agent-host/channels/pi-session-bridge.ts",
+          "version": "repo-file-v1:sha256:d8c3b8ac4aa6a6241e5756fa8f71df092d96ffdb5db4da9fc70530b08a894f0d"
