+      "statement": "Account, binding, state and media stores use atomic temp-file + rename writes with 0o600 modes; channel status and activity are checkpointed and pushed to the renderer.",
+      "evidence": [
+        {
+          "resource": "repo://src/agent-host/channels/config-store.ts",
+          "version": "repo-file-v1:sha256:bbd7999f26d44c682b9ca171da1e61261f21ba8c5e3ce4bcb07381a6b2bcde8d"
