+      "evidence": [
+        {
+          "resource": "repo://src/main/browser/browser-secret-vault.ts",
+          "version": "repo-file-v1:sha256:f5980b78588fd8a65e482874a39405a2054e0b5248fa435e499f1d8f73bd4d60"
