  readonly code: ManagedProcessErrorCode;
  readonly details?: Record<string, unknown>;

  constructor(code: ManagedProcessErrorCode, message: string, details?: Record<string, unknown>) {
    super(message);
    this.name = "ManagedProcessError";
    this.code = code;
