    binding: ChannelBinding,
    newSessionToolNames: string[] = binding.toolNames,
  ): Promise<OpenedSession> {
    this.prepareWorkspace(binding);

    if (binding.sessionId) {
      const existing = getRpcSession(binding.sessionId);
      if (existing?.isAlive()) {
